/**
 * Realistic edit-diff regression test for the markdown editor (#437/#440).
 *
 * The strict round-trip suite in test-markdown-editor-roundtrip.js asserts
 * that an UNTOUCHED document survives mount->getMarkdown() byte-for-byte.
 * That's the worst case for Tiptap, because it punishes any whitespace /
 * escape normalization the parser applies, even normalization a real user
 * would never notice.
 *
 * What actually matters in production is what the autosave loop in
 * controller.ts:scheduleAutosave does: it diffs `getMarkdown()` against
 * `state.fullDocumentContent` and emits `edit_block` calls for the diff.
 * If the diff is just the user's actual edit, the file is safe. If Tiptap
 * also normalizes 47 unrelated lines, those edit_blocks corrupt the file.
 *
 * This suite measures the *collateral damage* an edit produces:
 *   1. A whole-file rewrite (>=70% lines changed) is catastrophic — that's
 *      the path computeEditBlocks takes when too much of the document
 *      drifts. We assert this NEVER fires for a small user edit.
 *   2. The number of edit-block hunks should be small — ideally 1 (just
 *      the user's edit). Tolerated up to 3 to account for trivial Tiptap
 *      normalization at the boundaries.
 *   3. The user's actual change must appear in exactly one hunk and the
 *      surrounding text must be unmangled.
 */

import assert from 'assert';
import { JSDOM } from 'jsdom';

// jsdom for Tiptap to mount into.
const dom = new JSDOM('<!doctype html><html><body><div id="root"></div></body></html>');
globalThis.window = dom.window;
globalThis.document = dom.window.document;
globalThis.HTMLElement = dom.window.HTMLElement;
globalThis.Node = dom.window.Node;
globalThis.DOMParser = dom.window.DOMParser;
globalThis.getComputedStyle = dom.window.getComputedStyle;
// Tiptap's focus() calls requestAnimationFrame which jsdom doesn't ship
// by default. Stub with a synchronous no-op — we don't need real focus
// behaviour for these tests.
globalThis.requestAnimationFrame = (cb) => setTimeout(cb, 0);
globalThis.cancelAnimationFrame = (id) => clearTimeout(id);

const { Editor } = await import('@tiptap/core');
const editorMod = await import('../dist/ui/file-preview/src/markdown/editor.js');
const controllerMod = await import('../dist/ui/file-preview/src/markdown/controller.js');
const { preprocessForEditor, applyPostProcess, buildTiptapExtensions } = editorMod;
const { computeEditBlocks } = controllerMod;

/**
 * Mount the editor exactly as production does, return a handle that lets
 * the test:
 *   - apply a synthetic edit (insert text at a position, simulating typing)
 *   - read getMarkdown() through the production post-process pipeline
 *   - tear down cleanly
 */
function mountForEdit(input) {
  const target = document.getElementById('root');
  target.innerHTML = '';
  const { editorInput, context } = preprocessForEditor(input);
  const editor = new Editor({
    element: target,
    extensions: buildTiptapExtensions(),
    content: editorInput,
  });
  return {
    editor,
    /** Insert plain text at a ProseMirror doc position (simulates typing). */
    insertAt(pos, text) {
      editor.chain().focus().insertContentAt(pos, text).run();
    },
    /** Replace a text fragment in the document. Searches by visible text
     *  content; if the search string isn't found verbatim (e.g. it spans
     *  inline-code boundaries), falls back to the longest matching prefix. */
    replaceText(find, replace) {
      // Build the full visible text by concatenating all text nodes.
      // Track each text node's visible-text offset so we can map back.
      const segments = [];
      let visibleText = '';
      editor.state.doc.descendants((node, nodePos) => {
        if (node.isText) {
          segments.push({ pos: nodePos, text: node.text, start: visibleText.length });
          visibleText += node.text;
        }
        return true;
      });
      let idx = visibleText.indexOf(find);
      let matchLen = find.length;
      if (idx === -1) {
        // Try a relaxed match: drop punctuation characters that would
        // render via separate ProseMirror inline marks (backticks, etc.)
        const stripped = find.replace(/`/g, '');
        idx = visibleText.indexOf(stripped);
        if (idx === -1) {
          throw new Error(`replaceText: didn't find ${JSON.stringify(find)} (also tried ${JSON.stringify(stripped)})`);
        }
        matchLen = stripped.length;
      }
      // Map visible-text offset back to a ProseMirror position by
      // walking the segments.
      let from = -1;
      for (const seg of segments) {
        if (seg.start + seg.text.length > idx) {
          from = seg.pos + (idx - seg.start);
          break;
        }
      }
      if (from === -1) throw new Error('replaceText: position not found');
      editor.chain().focus().insertContentAt({ from, to: from + matchLen }, replace).run();
    },
    getMarkdown() {
      const storage = editor.storage;
      return applyPostProcess(storage.markdown?.getMarkdown() ?? '', context);
    },
    destroy() {
      editor.destroy();
    },
  };
}

let passed = 0;
let failed = 0;
function pass(name) { console.log('OK  ', name); passed++; }
function fail(name, detail) { console.log('FAIL', name); if (detail) console.log('     ', detail); failed++; }

/**
 * Core invariants we want every edit to obey.
 *
 * @param name human-readable test name
 * @param input the original markdown
 * @param edit (handle) => void — perform the synthetic edit on the editor
 * @param expectedSubstring — text we expect to find in the post-edit doc
 */
function assertEditDiffIsClean(name, input, edit, expectedSubstring) {
  const handle = mountForEdit(input);
  edit(handle);
  const after = handle.getMarkdown();
  handle.destroy();

  // 1. The user's edit must actually be in the output.
  if (!after.includes(expectedSubstring)) {
    return fail(name, `expected substring not in output: ${JSON.stringify(expectedSubstring)}`);
  }

  // 2. computeEditBlocks should not emit a whole-document rewrite.
  const oldLines = input.split('\n');
  const newLines = after.split('\n');
  const hunks = computeEditBlocks(input, after);

  if (hunks.length === 1) {
    const hunk = hunks[0];
    // Whole-file rewrite signature: old_string covers the entire input.
    if (hunk.old_string === input && hunk.new_string === after) {
      return fail(name, `WHOLE-FILE REWRITE — autosave would replace the entire document`);
    }
  }

  // 3. The number of hunks should be small. >3 means Tiptap is normalising
  //    multiple regions the user didn't touch.
  if (hunks.length > 3) {
    diagnoseDiff(input, after, hunks);
    return fail(name, `${hunks.length} hunks (>3); Tiptap is normalising unrelated regions`);
  }

  // 4. Total lines changed should be small relative to file size. Bound
  //    at 20% — anything bigger is collateral damage, not a real edit.
  const linesChanged = Math.abs(newLines.length - oldLines.length)
    + countDifferingLines(oldLines, newLines);
  if (oldLines.length > 0 && linesChanged / oldLines.length > 0.2) {
    diagnoseDiff(input, after, hunks);
    return fail(name,
      `${linesChanged} of ${oldLines.length} lines differ (>20%) for what should be a small edit`);
  }

  pass(`${name} (${hunks.length} hunk${hunks.length === 1 ? '' : 's'}, ${linesChanged} lines changed)`);
}

/** Print a compact summary of the diff so we can see what Tiptap is changing. */
function diagnoseDiff(before, after, hunks) {
  console.log('     hunks:', hunks.length);
  for (const [i, h] of hunks.entries()) {
    console.log(`     [${i}] OLD:`);
    for (const line of h.old_string.split('\n').slice(0, 8)) {
      console.log(`         ${JSON.stringify(line)}`);
    }
    console.log(`         NEW:`);
    for (const line of h.new_string.split('\n').slice(0, 8)) {
      console.log(`         ${JSON.stringify(line)}`);
    }
  }
}

function countDifferingLines(a, b) {
  // Cheap upper-bound on different lines: count positions where lines
  // disagree, allowing for length differences.
  let diff = 0;
  const min = Math.min(a.length, b.length);
  for (let i = 0; i < min; i += 1) {
    if (a[i] !== b[i]) diff += 1;
  }
  return diff;
}

const README = `# My Project

A short intro paragraph explaining what the project does.

## Installation

Install with the package manager:

\`\`\`bash
npm install my-project
\`\`\`

Then verify it works:

\`\`\`bash
my-project --version
\`\`\`

## Usage

The CLI accepts a few flags:

| Flag | Description | Default |
|---|---|---|
| \`--input\` | Input file | stdin |
| \`--output\` | Output file | stdout |
| \`--verbose\` | Verbose logs | false |

Run it like this:

\`\`\`bash
my-project --input data.json --output result.json
\`\`\`

## Development

To set up locally:

- Clone the repo
- Run \`npm install\`
- Run \`npm test\`

PRs welcome — please \`fork\` and submit against \`main\`.

## License

MIT.
`;

// --- Test 1: append a sentence to an existing paragraph ---
assertEditDiffIsClean(
  'append text to an existing paragraph',
  README,
  (h) => h.replaceText('A short intro paragraph explaining what the project does.',
    'A short intro paragraph explaining what the project does. New sentence added.'),
  'New sentence added.',
);

// --- Test 2: edit a heading (search by visible text — the rendered
//     heading is just "Usage", without the leading `## `) ---
assertEditDiffIsClean(
  'rename a heading',
  README,
  (h) => h.replaceText('Usage', 'How to use'),
  '## How to use',
);

// --- Test 3: append a new bullet at the end of an existing list. The
//     visible text for ``Run `npm test`'' is "Run npm test" — backticks
//     are inline-code mark boundaries, not part of the text. ---
assertEditDiffIsClean(
  'append a bullet to a list',
  README,
  (h) => h.replaceText('Run npm test', 'Run npm test\nRun npm run lint'),
  'npm run lint',
);

// --- Test 4: edit a single word in a paragraph ---
assertEditDiffIsClean(
  'fix a typo',
  README,
  (h) => h.replaceText('PRs welcome', 'PRs are welcome'),
  'PRs are welcome',
);

// --- Test 5: leave the file completely unchanged (no edit) ---
{
  const handle = mountForEdit(README);
  const after = handle.getMarkdown();
  handle.destroy();
  const hunks = computeEditBlocks(README, after);
  if (hunks.length === 0) {
    pass('no edit -> no hunks');
  } else if (hunks.length === 1 && hunks[0].old_string === README && hunks[0].new_string === after) {
    fail('no edit -> no hunks',
      `WHOLE-FILE REWRITE on an untouched file — Tiptap normalised the whole document`);
  } else {
    diagnoseDiff(README, after, hunks);
    fail('no edit -> no hunks',
      `expected 0 hunks for an untouched file, got ${hunks.length}`);
  }
}

// --- Test 6: edits to a document with frontmatter + wikilinks + tasks ---
const COMPLEX = `---
title: Notes
tags: [project, journal]
---

# Daily Log

See [[Project Roadmap]] for context.

## Tasks

- [x] Land the round-trip fix
- [ ] Write up the design doc
- [ ] Get review

## Progress

| Day | Focus | Notes |
|---|---|---|
| Mon | research | found root cause |
| Tue | implementation | wrappers + extensions |
| Wed | testing | 12/14 passing |

That's the week.
`;

assertEditDiffIsClean(
  'edit a paragraph in a doc with frontmatter + wikilinks + tasks + table',
  COMPLEX,
  (h) => h.replaceText("That's the week.", "That's the week. More to come."),
  'More to come.',
);

// Check that the no-edit case for the complex doc is also clean.
{
  const handle = mountForEdit(COMPLEX);
  const after = handle.getMarkdown();
  handle.destroy();
  const hunks = computeEditBlocks(COMPLEX, after);
  if (hunks.length === 0) {
    pass('no edit on complex doc -> no hunks');
  } else {
    diagnoseDiff(COMPLEX, after, hunks);
    fail('no edit on complex doc -> no hunks',
      `expected 0 hunks for an untouched complex doc, got ${hunks.length}`);
  }
}

console.log('\n' + passed + ' passed, ' + failed + ' failed');
process.exit(failed > 0 ? 1 : 0);

import { App } from '@modelcontextprotocol/ext-apps';
import { createToolBridge } from '../../shared/tool-bridge.js';
import { createCompactRowShellController, type ToolShellController } from '../../shared/tool-shell.js';
import { renderCompactRow } from '../../shared/compact-row.js';
import { escapeHtml } from '../../shared/escape-html.js';
import { createWidgetStateStorage } from '../../shared/widget-state.js';
import { connectWithSharedHostContext, isObjectRecord, type UiChromeState } from '../../shared/host-context.js';
import { createUiEventTracker, type UiEventParams } from '../../shared/ui-event-tracker.js';
import { createArrayModalController, renderArrayModalMarkup } from './array-modal.js';
import { CONFIG_FIELD_DEFINITIONS, isConfigFieldKey } from '../../../config-field-definitions.js';

export interface ConfigEntry {
    key: string;
    label?: string;
    description?: string;
    value: unknown;
    valueType: 'string' | 'number' | 'boolean' | 'array' | 'null' | string;
    editable: boolean;
}

export interface ConfigEditorPayload {
    config?: Record<string, unknown>;
    uiHints?: {
        availableShells?: string[];
    };
    entries: ConfigEntry[];
}

export interface ConfigEditorState {
    payload: ConfigEditorPayload | null;
    selectedKey: string | null;
    draftValue: string;
}

export type TooltipTone = 'info' | 'error' | 'success';

export interface TooltipMessage {
    message: string;
    tone: TooltipTone;
}

export interface ApplyConfigResult {
    ok: boolean;
    tooltip?: TooltipMessage;
}

interface RenderHooks {
    onConfigChanged?: (change: { key: string; value: unknown }) => void;
    onTooltip?: (tooltip: TooltipMessage) => void;
    onExpandedChanged?: (expanded: boolean) => void;
}

type ToolCall = (name: string, args?: Record<string, unknown>) => Promise<unknown>;
type TrackConfigUiEvent = (event: string, params?: Record<string, unknown>) => void;

let shellController: ToolShellController | undefined;

const CONFIG_EDITOR_COMPONENT = 'config_editor';
const GET_CONFIG_TOOL_NAME = 'get_config';
const MAX_TELEMETRY_MESSAGE_LENGTH = 180;

function sanitizeTelemetryErrorMessage(message: string): string {
    // Keep error signal useful while removing path-like data and bounding payload size.
    const collapsed = message.replace(/\s+/g, ' ').trim();
    const withoutPaths = collapsed
        .replace(/(?:\/|\\)[\w\d_.\-/\\]+/g, '[PATH]')
        .replace(/[A-Za-z]:\\[\w\d_.\-/\\]+/g, '[PATH]');

    if (withoutPaths.length === 0) {
        return 'Unknown error';
    }

    if (withoutPaths.length <= MAX_TELEMETRY_MESSAGE_LENGTH) {
        return withoutPaths;
    }

    return `${withoutPaths.slice(0, MAX_TELEMETRY_MESSAGE_LENGTH - 3)}...`;
}

function buildConfigUpdateTelemetryParams(args: {
    configKey: string;
    valueType: string;
    errorMessage?: string;
    errorStage?: 'set_config_value' | 'transport';
}): UiEventParams {
    const base: UiEventParams = {
        config_key: args.configKey,
        value_type: args.valueType,
    };

    if (args.errorStage) {
        base.error_stage = args.errorStage;
    }
    if (args.errorMessage) {
        base.error_message = sanitizeTelemetryErrorMessage(args.errorMessage);
    }

    return base;
}

function isConfigEditorPayload(value: unknown): value is ConfigEditorPayload {
    return isObjectRecord(value) && Array.isArray((value as Record<string, unknown>).entries);
}

function stringifyValueForInput(value: unknown): string {
    if (Array.isArray(value)) {
        return value.map((item) => String(item)).join('\n');
    }
    if (typeof value === 'string') {
        return value;
    }
    if (typeof value === 'number' || typeof value === 'boolean') {
        return String(value);
    }
    if (value === null) {
        return 'null';
    }
    try {
        return JSON.stringify(value);
    } catch {
        return String(value);
    }
}

function formatKeyLabel(key: string): string {
    return key
        .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
        .replace(/[_-]+/g, ' ')
        .trim()
        .split(/\s+/)
        .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
        .join(' ');
}

function getConfigFieldMetadata(key: string): { label: string; description: string } | undefined {
    if (!isConfigFieldKey(key)) {
        return undefined;
    }
    return {
        label: CONFIG_FIELD_DEFINITIONS[key].label,
        description: CONFIG_FIELD_DEFINITIONS[key].description,
    };
}

function extractPayload(result: unknown): ConfigEditorPayload | null {
    if (!isObjectRecord(result)) {
        return null;
    }
    const structured = result.structuredContent;
    if (!isObjectRecord(structured) || !Array.isArray(structured.entries)) {
        return null;
    }

    const entries: ConfigEntry[] = structured.entries
        .filter((entry): entry is Record<string, unknown> => isObjectRecord(entry))
        .filter((entry) => typeof entry.key === 'string')
        .map((entry) => {
            const key = entry.key as string;
            const metadata = getConfigFieldMetadata(key);
            return {
                key,
                label: metadata?.label,
                description: metadata?.description,
                value: entry.value,
                valueType: typeof entry.valueType === 'string' ? entry.valueType : 'string',
                editable: entry.editable !== false,
            };
        });

    return {
        config: isObjectRecord(structured.config) ? structured.config : undefined,
        uiHints: isObjectRecord(structured.uiHints)
            ? {
                availableShells: Array.isArray(structured.uiHints.availableShells)
                    ? structured.uiHints.availableShells.filter((value): value is string => typeof value === 'string')
                    : undefined,
            }
            : undefined,
        entries,
    };
}

function extractToolText(result: unknown): string | undefined {
    if (!isObjectRecord(result) || !Array.isArray(result.content)) {
        return undefined;
    }

    for (const item of result.content) {
        if (!isObjectRecord(item)) {
            continue;
        }
        if (item.type === 'text' && typeof item.text === 'string' && item.text.trim().length > 0) {
            return item.text;
        }
    }

    return undefined;
}

function isToolErrorResult(result: unknown): boolean {
    return isObjectRecord(result) && result.isError === true;
}

function parseDraftValue(rawValue: string, valueType: string): { ok: true; value: unknown } | { ok: false; message: string } {
    if (valueType === 'string') {
        return { ok: true, value: rawValue.replace(/\r?\n/g, ' ') };
    }

    if (valueType === 'number') {
        if (rawValue.trim() === '') {
            return { ok: false, message: 'Enter a valid number.' };
        }
        const numeric = Number(rawValue);
        if (!Number.isFinite(numeric)) {
            return { ok: false, message: 'Enter a valid number.' };
        }
        return { ok: true, value: numeric };
    }

    if (valueType === 'boolean') {
        const normalized = rawValue.trim().toLowerCase();
        if (normalized !== 'true' && normalized !== 'false') {
            return { ok: false, message: 'Boolean values must be true or false.' };
        }
        return { ok: true, value: normalized === 'true' };
    }

    if (valueType === 'null') {
        if (rawValue.trim().toLowerCase() !== 'null') {
            return { ok: false, message: 'Null values must be exactly null.' };
        }
        return { ok: true, value: null };
    }

    if (valueType === 'array') {
        const trimmed = rawValue.trim();
        if (trimmed.length === 0) {
            return { ok: true, value: [] };
        }

        if (!trimmed.startsWith('[')) {
            const items = rawValue
                .split(/\r?\n/)
                .map((item) => item.trim())
                .filter((item) => item.length > 0);
            return { ok: true, value: items };
        }

        try {
            const parsed = JSON.parse(trimmed);
            if (!Array.isArray(parsed)) {
                return { ok: false, message: 'Array values must be valid JSON arrays.' };
            }
            if (!parsed.every((item) => typeof item === 'string')) {
                return { ok: false, message: 'Array values must contain only strings.' };
            }
            return { ok: true, value: parsed };
        } catch {
            return { ok: false, message: 'Array values must be valid JSON arrays.' };
        }
    }

    return { ok: true, value: rawValue };
}

function areConfigValuesEqual(left: unknown, right: unknown): boolean {
    if (Object.is(left, right)) {
        return true;
    }

    if (Array.isArray(left) && Array.isArray(right)) {
        if (left.length !== right.length) {
            return false;
        }

        for (let index = 0; index < left.length; index += 1) {
            if (!Object.is(left[index], right[index])) {
                return false;
            }
        }

        return true;
    }

    return false;
}

function parseDraftArrayValues(draft: string): string[] {
    const trimmed = draft.trim();
    if (!trimmed) {
        return [];
    }
    if (trimmed.startsWith('[')) {
        try {
            const parsed = JSON.parse(trimmed);
            if (Array.isArray(parsed)) {
                return parsed.filter((item) => typeof item === 'string') as string[];
            }
        } catch {
            // fallback below
        }
    }
    return draft
        .split(/\r?\n/)
        .map((line) => line.trim())
        .filter((line) => line.length > 0);
}

function getSettingSummary(entry: ConfigEntry): string | null {
    if (entry.key !== 'blockedCommands' && entry.key !== 'allowedDirectories') {
        return null;
    }

    const values = Array.isArray(entry.value)
        ? entry.value.filter((item) => typeof item === 'string' && item.trim().length > 0)
        : [];

    const count = values.length;
    if (entry.key === 'blockedCommands') {
        return `${count} command${count === 1 ? '' : 's'} blocked`;
    }

    if (count === 0) {
        return 'All folders allowed (no restriction)';
    }

    return `${count} folder${count === 1 ? '' : 's'} allowed`;
}

function getShellOptions(payload: ConfigEditorPayload | null, currentShell: string): string[] {
    const hintedShells = Array.isArray(payload?.uiHints?.availableShells)
        ? payload.uiHints.availableShells.filter((shell): shell is string => typeof shell === 'string' && shell.trim().length > 0)
        : [];

    const config = payload?.config;
    const systemInfo = isObjectRecord(config?.systemInfo) ? config.systemInfo : null;
    const isWindows = Boolean(systemInfo && systemInfo.isWindows === true);
    const isMacOS = Boolean(systemInfo && systemInfo.isMacOS === true);

    const baseOptions = hintedShells.length > 0
        ? hintedShells
        : isWindows
            ? ['powershell.exe', 'pwsh.exe', 'cmd.exe', 'bash.exe']
            : isMacOS
                ? ['/bin/zsh', '/bin/bash', '/bin/sh', '/usr/bin/fish', 'zsh', 'bash', 'sh', 'fish']
                : ['/bin/bash', '/bin/sh', '/usr/bin/fish', '/bin/zsh', 'bash', 'sh', 'fish', 'zsh'];

    const options = new Set<string>();
    for (const shell of baseOptions) {
        options.add(shell);
    }
    if (currentShell.trim().length > 0) {
        options.add(currentShell);
    }

    return [...options];
}

export function createConfigEditorController(callTool: ToolCall, trackConfigUiEvent?: TrackConfigUiEvent) {
    const state: ConfigEditorState = {
        payload: null,
        selectedKey: null,
        draftValue: '',
    };

    const getSelectedEntry = (): ConfigEntry | undefined => {
        if (!state.payload || !state.selectedKey) {
            return undefined;
        }
        return state.payload.entries.find((entry) => entry.key === state.selectedKey);
    };

    const setPayload = (payload: ConfigEditorPayload | null): void => {
        state.payload = payload;
        if (!payload || payload.entries.length === 0) {
            state.selectedKey = null;
            state.draftValue = '';
            return;
        }

        if (!state.selectedKey || !payload.entries.some((entry) => entry.key === state.selectedKey)) {
            state.selectedKey = payload.entries[0].key;
        }

        const current = getSelectedEntry();
        state.draftValue = current ? stringifyValueForInput(current.value) : '';
    };

    const setSelection = (key: string): void => {
        state.selectedKey = key;
        const selected = getSelectedEntry();
        state.draftValue = selected ? stringifyValueForInput(selected.value) : '';
    };

    const setDraftValue = (value: string): void => {
        state.draftValue = value;
    };

    const apply = async (): Promise<ApplyConfigResult> => {
        const selected = getSelectedEntry();
        if (!selected) {
            return {
                ok: false,
                tooltip: {
                    message: 'Select a config key before applying.',
                    tone: 'error',
                },
            };
        }

        if (!selected.editable) {
            return {
                ok: false,
                tooltip: {
                    message: `The selected key (${selected.key}) is read-only.`,
                    tone: 'error',
                },
            };
        }

        const parsed = parseDraftValue(state.draftValue, selected.valueType);
        if (!parsed.ok) {
            return {
                ok: false,
                tooltip: {
                    message: parsed.message,
                    tone: 'error',
                },
            };
        }

        if (areConfigValuesEqual(parsed.value, selected.value)) {
            state.draftValue = stringifyValueForInput(selected.value);
            return { ok: false };
        }

        try {
            const setResult = await callTool('set_config_value', {
                key: selected.key,
                value: parsed.value,
                origin: 'ui',
            });

            if (isToolErrorResult(setResult)) {
                const errorMessage = extractToolText(setResult) ?? `Failed to update ${selected.key}.`;
                trackConfigUiEvent?.('config_update_failed', {
                    tool_name: 'set_config_value',
                    ...buildConfigUpdateTelemetryParams({
                        configKey: selected.key,
                        valueType: selected.valueType,
                        errorMessage,
                        errorStage: 'set_config_value',
                    }),
                });

                return {
                    ok: false,
                    tooltip: {
                        message: errorMessage,
                        tone: 'error',
                    },
                };
            }

            trackConfigUiEvent?.('config_update_success', {
                tool_name: 'set_config_value',
                ...buildConfigUpdateTelemetryParams({
                    configKey: selected.key,
                    valueType: selected.valueType,
                }),
            });

            const refreshed = await callTool('get_config', { origin: 'ui' });
            if (isToolErrorResult(refreshed)) {
                const errorMessage = extractToolText(refreshed) ?? 'Value was updated but config refresh failed.';
                return {
                    ok: false,
                    tooltip: {
                        message: errorMessage,
                        tone: 'error',
                    },
                };
            }

            const refreshedPayload = extractPayload(refreshed);
            if (refreshedPayload) {
                setPayload(refreshedPayload);
                if (state.selectedKey === selected.key) {
                    const updatedSelected = getSelectedEntry();
                    state.draftValue = updatedSelected
                        ? stringifyValueForInput(updatedSelected.value)
                        : state.draftValue;
                }
            }

            return {
                ok: true,
            };
        } catch (error) {
            const errorMessage = `Failed to apply value: ${error instanceof Error ? error.message : String(error)}`;
            trackConfigUiEvent?.('config_update_failed', {
                tool_name: 'set_config_value',
                ...buildConfigUpdateTelemetryParams({
                    configKey: selected.key,
                    valueType: selected.valueType,
                    errorMessage,
                    errorStage: 'transport',
                }),
            });

            return {
                ok: false,
                tooltip: {
                    message: errorMessage,
                    tone: 'error',
                },
            };
        }
    };

    return {
        state,
        callTool,
        extractPayload,
        setPayload,
        setSelection,
        setDraftValue,
        apply,
    };
}

function render(container: HTMLElement, controller: ReturnType<typeof createConfigEditorController>, chrome: UiChromeState, hooks: RenderHooks = {}): void {
    shellController?.dispose();
    shellController = undefined;

    const { state } = controller;
    const entries = state.payload?.entries ?? [];
    const shellClasses = [
        'shell',
        'tool-shell',
        chrome.expanded ? 'expanded' : 'collapsed',
        'config-shell',
        chrome.hideSummaryRow ? 'host-framed' : '',
        chrome.compact ? 'compact' : '',
    ].filter(Boolean).join(' ');

    const settingsHtml = entries.map((entry, index) => {
        const keyTitle = entry.label ?? formatKeyLabel(entry.key);
        const description = entry.description ?? '';
        const summary = getSettingSummary(entry);

        let controlHtml: string;
        if (entry.key === 'defaultShell') {
            const currentShell = String(entry.value ?? '');
            const shellOptions = getShellOptions(state.payload, currentShell);
            const isCustomShell = !shellOptions.includes(currentShell);
            const options = shellOptions
                .map((shell) => `<option value="${escapeHtml(shell)}" ${shell === currentShell ? 'selected' : ''}>${escapeHtml(shell)}</option>`)
                .join('');
            controlHtml = `
                <div class="setting-shell-control">
                  <select class="setting-inline-select" data-action="shell-select" data-key-index="${index}">
                    ${options}
                    <option value="__custom__" ${isCustomShell ? 'selected' : ''}>Custom...</option>
                  </select>
                  <input class="setting-inline-input setting-shell-custom${isCustomShell ? '' : ' hidden'}" data-action="shell-custom" data-key-index="${index}" type="text" value="${escapeHtml(currentShell)}" placeholder="Type custom shell path"/>
                </div>
            `;
        } else if (entry.valueType === 'boolean') {
            const checked = String(entry.value) === 'true' ? 'checked' : '';
            controlHtml = `<label class="setting-switch"><input type="checkbox" data-action="toggle-boolean" data-key-index="${index}" ${checked}/><span class="config-boolean-slider"></span></label>`;
        } else if (entry.valueType === 'number') {
            controlHtml = `<input class="setting-inline-input" data-action="edit-number" data-key-index="${index}" type="number" step="any" value="${escapeHtml(String(entry.value ?? ''))}"/>`;
        } else if (entry.valueType === 'array') {
            controlHtml = `<button class="setting-inline-action" data-action="open-array" data-key-index="${index}">Edit</button>`;
        } else if (entry.valueType === 'null') {
            controlHtml = `<span class="setting-inline-static">null</span>`;
        } else {
            controlHtml = `<input class="setting-inline-input" data-action="edit-string" data-key-index="${index}" type="text" value="${escapeHtml(String(entry.value ?? ''))}"/>`;
        }

        return `
          <section class="setting-row">
            <div class="setting-info">
              <h3>${escapeHtml(keyTitle)}</h3>
              ${description ? `<p>${escapeHtml(description)}</p>` : ''}
              <p class="setting-summary${summary ? '' : ' hidden'}" data-setting-summary-key="${escapeHtml(entry.key)}">${summary ? escapeHtml(summary) : ''}</p>
            </div>
            <div class="setting-control">${controlHtml}</div>
          </section>
        `;
    }).join('');

    container.innerHTML = `
      <main id="tool-shell" class="${shellClasses}">
        ${renderCompactRow({ id: 'compact-toggle', label: 'View config', filename: 'Desktop Commander', variant: 'ready', expandable: true, expanded: chrome.expanded, interactive: true })}

        <section class="panel config-card">
          <div class="panel-content-wrapper">
            <div class="settings-stack" aria-label="Desktop Commander settings">${settingsHtml}</div>
          </div>
        </section>

        ${renderArrayModalMarkup('List Setting')}
      </main>
      <div id="config-tooltip" class="config-tooltip" role="status" aria-live="polite" hidden></div>
    `;

    const toolShell = container.querySelector('#tool-shell') as HTMLElement | null;
    const compactRow = container.querySelector('.compact-row--ready') as HTMLElement | null;

    const getUpdatedEntryByKey = (key: string): ConfigEntry | undefined => {
        return controller.state.payload?.entries.find((item) => item.key === key);
    };

    const refreshSettingSummary = (key: string): void => {
        const summaryElement = container.querySelector(`[data-setting-summary-key="${key}"]`) as HTMLElement | null;
        if (!summaryElement) {
            return;
        }
        const updatedEntry = getUpdatedEntryByKey(key);
        const summary = updatedEntry ? getSettingSummary(updatedEntry) : null;
        summaryElement.textContent = summary ?? '';
        summaryElement.classList.toggle('hidden', !summary);
    };

    const emitConfigChanged = (key: string, fallbackValue: unknown): void => {
        const updatedEntry = getUpdatedEntryByKey(key);
        refreshSettingSummary(key);
        hooks.onConfigChanged?.({
            key,
            value: updatedEntry ? updatedEntry.value : fallbackValue,
        });
    };

    const emitTooltip = (result: ApplyConfigResult): void => {
        if (result.tooltip) {
            hooks.onTooltip?.(result.tooltip);
        }
    };

    const arrayModal = createArrayModalController({
        container,
        parseEntryItems: (entry) => parseDraftArrayValues(stringifyValueForInput(entry.value)),
        formatEntryTitle: (entry) => entry.label ?? formatKeyLabel(entry.key),
        onSave: async (changedKey, items) => {
            controller.setSelection(changedKey);
            controller.setDraftValue(items.join('\n'));
            const result = await controller.apply();
            emitTooltip(result);
            if (result.ok) {
                emitConfigChanged(changedKey, items);
            }
        },
    });

    container.querySelectorAll('[data-action]').forEach((element) => {
        const target = element as HTMLElement;
        const action = target.dataset.action;
        const keyIndex = Number(target.dataset.keyIndex);
        const entry = entries[keyIndex];
        if (!entry) {
            return;
        }

        if (action === 'toggle-boolean') {
            target.addEventListener('change', async () => {
                const input = target as HTMLInputElement;
                const previousChecked = input.checked;
                controller.setSelection(entry.key);
                controller.setDraftValue(input.checked ? 'true' : 'false');
                const result = await controller.apply();
                emitTooltip(result);
                const updatedEntry = getUpdatedEntryByKey(entry.key);
                if (updatedEntry && typeof updatedEntry.value === 'boolean') {
                    input.checked = updatedEntry.value;
                } else if (!result.ok) {
                    input.checked = !previousChecked;
                }
                if (result.ok) {
                    emitConfigChanged(entry.key, input.checked);
                }
            });
            return;
        }

        if (action === 'edit-number') {
            target.addEventListener('blur', async () => {
                const input = target as HTMLInputElement;
                controller.setSelection(entry.key);
                controller.setDraftValue(input.value);
                const result = await controller.apply();
                emitTooltip(result);
                const updatedEntry = getUpdatedEntryByKey(entry.key);
                input.value = String(updatedEntry?.value ?? controller.state.draftValue);
                if (result.ok) {
                    emitConfigChanged(entry.key, input.value);
                }
            });
            return;
        }

        if (action === 'shell-select') {
            target.addEventListener('change', async () => {
                const select = target as HTMLSelectElement;
                const customInput = container.querySelector(`input[data-action="shell-custom"][data-key-index="${keyIndex}"]`) as HTMLInputElement | null;
                if (select.value === '__custom__') {
                    customInput?.classList.remove('hidden');
                    customInput?.focus();
                    return;
                }

                customInput?.classList.add('hidden');
                controller.setSelection(entry.key);
                controller.setDraftValue(select.value);
                const result = await controller.apply();
                emitTooltip(result);
                const updatedEntry = getUpdatedEntryByKey(entry.key);
                const shellValue = String(updatedEntry?.value ?? select.value);
                const shellCustomInput = container.querySelector(`input[data-action="shell-custom"][data-key-index="${keyIndex}"]`) as HTMLInputElement | null;
                if (shellCustomInput) {
                    shellCustomInput.value = shellValue;
                }
                if (result.ok) {
                    emitConfigChanged(entry.key, shellValue);
                }
            });
            return;
        }

        if (action === 'shell-custom') {
            const commitCustomShell = async () => {
                const input = target as HTMLInputElement;
                if (!input.value.trim()) {
                    return;
                }
                controller.setSelection(entry.key);
                controller.setDraftValue(input.value.trim());
                const result = await controller.apply();
                emitTooltip(result);
                const updatedEntry = getUpdatedEntryByKey(entry.key);
                input.value = String(updatedEntry?.value ?? controller.state.draftValue);
                if (result.ok) {
                    emitConfigChanged(entry.key, input.value);
                }
            };

            target.addEventListener('blur', () => {
                void commitCustomShell();
            });

            target.addEventListener('keydown', (event) => {
                if (event.key !== 'Enter') {
                    return;
                }
                event.preventDefault();
                void commitCustomShell();
            });
            return;
        }

        if (action === 'edit-string') {
            target.addEventListener('keydown', async (event) => {
                if (event.key !== 'Enter') {
                    return;
                }
                event.preventDefault();
                const input = target as HTMLInputElement;
                controller.setSelection(entry.key);
                controller.setDraftValue(input.value.replace(/\r?\n/g, ' '));
                const result = await controller.apply();
                emitTooltip(result);
                const updatedEntry = getUpdatedEntryByKey(entry.key);
                input.value = String(updatedEntry?.value ?? controller.state.draftValue);
                if (result.ok) {
                    emitConfigChanged(entry.key, input.value);
                }
            });
            return;
        }

        if (action === 'open-array') {
            target.addEventListener('click', () => {
                const latestEntry = getUpdatedEntryByKey(entry.key) ?? entry;
                arrayModal.open(latestEntry);
            });
        }
    });

    shellController = createCompactRowShellController({
        shell: toolShell,
        compactRow,
        initialExpanded: chrome.expanded,
        onToggle: (expanded) => {
            chrome.expanded = expanded;
            hooks.onExpandedChanged?.(expanded);
        },
    });
}

